import { dartConstants } from "./constants";
import { classDeclaration } from "./dart-class";
import { DartCodec } from "./dart-codec";
import { dartString, enumMemberName, partFileName, typeName } from "./dart-names";
import { DART_RUNTIME, JSON_VALUE_DECLARATION } from "./dart-runtime";
import { sharedFields } from "./dart-union";
import { byCodeUnits } from "./order";
import { type TypeDef, tagValue } from "./type-model";

type UnionDef = Extract<TypeDef, { kind: "union" }>;
type EnumDef = Extract<TypeDef, { kind: "enum" }>;

export const GENERATED_HEADER =
	"// GENERATED by packages/bridge/scripts/gen-contract.ts from the zod schemas in\n" +
	"// packages/bridge/src/contract. Do not edit; change the schema and regenerate.\n";

export const LIBRARY_FILE = "contract.dart";

/** The generated library: `contract.dart` and one part per contract module, keyed by file name. */
export function dartLibrary(
	types: Map<string, TypeDef>,
	protocol: { major: number; minor: number },
	constants: [string, number][],
): Map<string, string> {
	const codec = new DartCodec(types);
	const unionsOf = unionMembership(types);
	const byModule = new Map<string, TypeDef[]>();
	for (const type of types.values()) byModule.set(type.module, [...(byModule.get(type.module) ?? []), type]);
	const modules = [...byModule.entries()].sort(([a], [b]) => byCodeUnits(a, b));
	const files = new Map<string, string>();
	files.set(
		LIBRARY_FILE,
		libraryFile(
			modules.map(([module]) => module),
			protocol,
			constants,
		),
	);
	for (const [module, moduleTypes] of modules) {
		const declarations = moduleTypes
			.sort((a, b) => byCodeUnits(a.name, b.name))
			.map((type) => declaration(type, types, codec, unionsOf));
		files.set(partFileName(module), `${GENERATED_HEADER}\npart of '${LIBRARY_FILE}';\n\n${declarations.join("\n")}`);
	}
	return files;
}

function libraryFile(
	modules: string[],
	protocol: { major: number; minor: number },
	constants: [string, number][],
): string {
	const parts = modules.map((module) => `part '${partFileName(module)}';`).join("\n");
	return (
		`${GENERATED_HEADER}\nlibrary;\n\n${parts}\n\n` +
		`const int contractProtocolMajor = ${protocol.major};\n` +
		`const int contractProtocolMinor = ${protocol.minor};\n\n` +
		`${dartConstants(constants)}\n` +
		DART_RUNTIME
	);
}

function unionMembership(types: Map<string, TypeDef>): Map<string, UnionDef[]> {
	const unionsOf = new Map<string, UnionDef[]>();
	for (const type of types.values()) {
		if (type.kind !== "union") continue;
		for (const member of type.members) unionsOf.set(member, [...(unionsOf.get(member) ?? []), type]);
	}
	return unionsOf;
}

function declaration(
	type: TypeDef,
	types: Map<string, TypeDef>,
	codec: DartCodec,
	unionsOf: Map<string, UnionDef[]>,
): string {
	switch (type.kind) {
		case "enum":
			return enumDeclaration(type);
		case "class": {
			const unions = unionsOf.get(type.name) ?? [];
			const inherited = new Set(
				unions.flatMap((union) => sharedFields(union, types, codec).map((field) => field.name)),
			);
			return classDeclaration(type, codec, unions, inherited);
		}
		case "union":
			return unionDeclaration(type, types, codec);
		case "alias":
			return `typedef ${typeName(type.name)} = ${codec.type(type.target)};\n`;
		case "json":
			return JSON_VALUE_DECLARATION;
	}
}

function enumDeclaration(type: EnumDef): string {
	const name = typeName(type.name);
	const members = type.values.map((wire) => `  ${enumMemberName(name, wire)}(${dartString(wire)})`).join(",\n");
	return `enum ${name} {
${members};

  const ${name}(this.wire);

  factory ${name}.fromJson(String json) => values.firstWhere(
    (value) => value.wire == json,
    orElse: () => throw FormatException('Unknown ${name}: $json'),
  );

  final String wire;

  String toJson() => wire;
}
`;
}

function unionDeclaration(type: UnionDef, types: Map<string, TypeDef>, codec: DartCodec): string {
	const name = typeName(type.name);
	const getters = sharedFields(type, types, codec)
		.map((field) => `  ${field.type} get ${field.name};\n\n`)
		.join("");
	const cases = type.members
		.map((member) => {
			const memberDef = types.get(member);
			if (memberDef?.kind !== "class") throw new Error(`${name}: member ${member} is not a class`);
			return `    ${dartString(tagValue(memberDef, type.key))} => ${member}.fromJson(json),\n`;
		})
		.join("");
	return `sealed class ${name} {
  factory ${name}.fromJson(Map<String, Object?> json) => switch (json[${dartString(type.key)}]) {
${cases}    final tag => throw FormatException('Unknown ${name} ${type.key}: $tag'),
  };

${getters}  Map<String, Object?> toJson();
}
`;
}
